// Fast case-insensitive lookup map
const lowerMap = new Map<string, string>();
for (const [k, v] of Object.entries(masterDictionary)) {
    const lower = k.toLowerCase().trim();
    if (!lowerMap.has(lower)) {
        lowerMap.set(lower, v);
    }
}

// Advanced pattern matchers for dynamic clinical strings
const patterns: Array<{ regex: RegExp; replace: (match: RegExpMatchArray) => string }> = [
    // "Toplam X Cihaz" -> "Total X Devices"
    {
        regex: /^Toplam\s+([0-9.,]+)\s+Cihaz$/i,
        replace: (m) => `Total ${m[1]} Devices`
    },
    // "Toplam X Kayıt" -> "Total X Records"
    {
        regex: /^Toplam\s+([0-9.,]+)\s+Kayıt$/i,
        replace: (m) => `Total ${m[1]} Records`
    },
    // "X adet cihaz" -> "X devices"
    {
        regex: /^([0-9.,]+)\s+adet\s+cihaz$/i,
        replace: (m) => `${m[1]} devices`
    },
    // "X adet kayıt" -> "X records"
    {
        regex: /^([0-9.,]+)\s+adet\s+kayıt$/i,
        replace: (m) => `${m[1]} records`
    },
    // "X gün kaldı" -> "X days remaining"
    {
        regex: /^([0-9.,]+)\s+gün\s+kaldı$/i,
        replace: (m) => `${m[1]} days remaining`
    },
    // "X gün geçti" -> "X days overdue"
    {
        regex: /^([0-9.,]+)\s+gün\s+geçti$/i,
        replace: (m) => `${m[1]} days overdue`
    },
    // "Son güncelleme: [date]" -> "Last updated: [date]"
    {
        regex: /^Son\s+güncelleme:\s*(.*)$/i,
        replace: (m) => `Last updated: ${m[1]}`
    },
    // "Durum: [status]" -> "Status: [status]"
    {
        regex: /^Durum:\s*(.*)$/i,
        replace: (m) => {
            const val = m[1].trim();
            const trVal = masterDictionary[val] || lowerMap.get(val.toLowerCase()) || val;
            return `Status: ${trVal}`;
        }
    },
    // "Öncelik: [priority]" -> "Priority: [priority]"
    {
        regex: /^Öncelik:\s*(.*)$/i,
        replace: (m) => {
            const val = m[1].trim();
            const trVal = masterDictionary[val] || lowerMap.get(val.toLowerCase()) || val;
            return `Priority: ${trVal}`;
        }
    },
    // "Kategori: [category]" -> "Category: [category]"
    {
        regex: /^Kategori:\s*(.*)$/i,
        replace: (m) => {
            const val = m[1].trim();
            const trVal = masterDictionary[val] || lowerMap.get(val.toLowerCase()) || val;
            return `Category: ${trVal}`;
        }
    },
    // "Bölüm: [dept]" -> "Department: [dept]"
    {
        regex: /^Bölüm:\s*(.*)$/i,
        replace: (m) => {
            const val = m[1].trim();
            const trVal = masterDictionary[val] || lowerMap.get(val.toLowerCase()) || val;
            return `Department: ${trVal}`;
        }
    },
    // "Hastane: [hosp]" -> "Hospital: [hosp]"
    {
        regex: /^Hastane:\s*(.*)$/i,
        replace: (m) => {
            const val = m[1].trim();
            const trVal = masterDictionary[val] || lowerMap.get(val.toLowerCase()) || val;
            return `Hospital: ${trVal}`;
        }
    }
];

export function translateText(rawText: string, lang: 'tr' | 'en'): string {
    if (lang !== 'en' || !rawText || typeof rawText !== 'string') {
        return rawText;
    }

    const trimmed = rawText.trim();
    if (!trimmed || trimmed.length < 2) {
        return rawText;
    }

    // 1. Direct match
    if (masterDictionary[trimmed]) {
        return rawText.replace(trimmed, masterDictionary[trimmed]);
    }

    // 2. Case-insensitive lookup
    const lowerMatch = lowerMap.get(trimmed.toLowerCase());
    if (lowerMatch) {
        return rawText.replace(trimmed, lowerMatch);
    }

    // 3. Pattern match
    for (const p of patterns) {
        const m = trimmed.match(p.regex);
        if (m) {
            return rawText.replace(trimmed, p.replace(m));
        }
    }

    // 4. Punctuation / whitespace trimming match
    const puncMatch = trimmed.match(/^([^a-zA-Z0-9çğıöşüÇĞİÖŞÜ]*)(.*?)([:.!?…\s]*)$/);
    if (puncMatch) {
        const [, lead, core, tail] = puncMatch;
        const coreLower = core.toLowerCase().trim();
        const coreTrans = masterDictionary[core] || lowerMap.get(coreLower);
        if (coreTrans) {
            return rawText.replace(trimmed, lead + coreTrans + tail);
        }
    }

    // 5. Compound "Label: Value" match where Label is known
    const colonIdx = trimmed.indexOf(':');
    if (colonIdx > 1 && colonIdx < trimmed.length - 1) {
        const left = trimmed.slice(0, colonIdx).trim();
        const right = trimmed.slice(colonIdx + 1).trim();
        const trLeft = masterDictionary[left] || lowerMap.get(left.toLowerCase());
        if (trLeft) {
            const trRight = masterDictionary[right] || lowerMap.get(right.toLowerCase()) || right;
            return rawText.replace(trimmed, `${trLeft}: ${trRight}`);
        }
    }

    return rawText;
}
